# fastapi/applications.py:4459-4466  (fastapi.applications.FastAPI.websocket_route)
class FastAPI(Starlette):
    def websocket_route(
        self, path: str, name: Union[str, None] = None
    ) -> Callable[[DecoratedCallable], DecoratedCallable]:
        def decorator(func: DecoratedCallable) -> DecoratedCallable:
            self.router.add_websocket_route(path, func, name=name)
            return func

        return decorator

# fastapi/routing.py:1114-1121  (fastapi.routing.APIRouter.websocket_route)
class APIRouter(routing.Router):
    def websocket_route(
        self, path: str, name: Union[str, None] = None
    ) -> Callable[[DecoratedCallable], DecoratedCallable]:
        def decorator(func: DecoratedCallable) -> DecoratedCallable:
            self.add_websocket_route(path, func, name=name)
            return func

        return decorator

# fastapi/routing.py:422-426  (fastapi.routing.APIWebSocketRoute.matches)
class APIWebSocketRoute(routing.WebSocketRoute):
    def matches(self, scope: Scope) -> Tuple[Match, Scope]:
        match, child_scope = super().matches(scope)
        if match != Match.NONE:
            child_scope["route"] = self
        return match, child_scope
